(()=>{const ids=['packPrice','packCount','runtime'];const update=()=>{const [price,count,time]=ids.map(id=>Number(document.getElementById(id).value));const out=document.getElementById('valueResult');if(!(price>0&&count>=1&&Number.isInteger(count)&&time>0)){out.textContent='양수 가격·사용시간과 정수 개수를 입력하세요.';return;}const unit=price/count;out.textContent=`개당 ${unit.toLocaleString('ko-KR',{maximumFractionDigits:1})}원 · 시간당 ${(unit/time).toLocaleString('ko-KR',{maximumFractionDigits:2})}원 · 100원당 ${(100*time/unit).toLocaleString('ko-KR',{maximumFractionDigits:2})}시간`;};ids.forEach(id=>document.getElementById(id).addEventListener('input',update));update();})();
